"""Abstract interface for memory systems."""

import hashlib
import json
import re
import threading
from abc import ABC, abstractmethod
from typing import Any

from .llm import LLMCallable


def extract_json_field(text: str, field: str, default: str = "") -> str:
    """Helper function to extract a field from JSON in LLM response."""
    # Try direct parse
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return str(data.get(field, default))
    except json.JSONDecodeError:
        pass

    # Try code blocks: ```json ... ``` or ``` ... ```
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(match.group(1))
            if isinstance(data, dict):
                return str(data.get(field, default))
        except json.JSONDecodeError:
            pass

    # Find balanced braces and try parsing
    for start in range(len(text)):
        if text[start] != "{":
            continue
        depth, pos, in_str = 1, start + 1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos - 1] != "\\"):
                in_str = not in_str
            elif not in_str:
                depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            candidate = text[start:pos]
            candidate = re.sub(
                r",\s*([\]}])", r"\1", candidate
            )  # Remove trailing commas
            try:
                data = json.loads(candidate)
                if isinstance(data, dict):
                    return str(data.get(field, default))
            except json.JSONDecodeError:
                pass

    # Regex fallback
    match = re.findall(rf'"{field}"\s*:\s*"([^"]*)"', text)
    return match[-1] if match else default


class MemorySystem(ABC):
    """Memory system interface for online and offline learning.

    Args:
        llm: Callable that takes a prompt string and returns a response string.
    """

    def __init__(self, llm: LLMCallable):
        self._llm = llm
        self._prompt_local = threading.local()

    def call_llm(self, prompt: str) -> str:
        """Call the LLM with a prompt. Tracks last prompt length/hash per thread."""
        self._prompt_local.last_prompt_len = len(prompt)
        self._prompt_local.last_prompt_hash = hashlib.md5(prompt.encode()).hexdigest()[
            :8
        ]
        self._prompt_local.last_prompt_text = prompt
        return self._llm(prompt)

    def get_last_prompt_info(self) -> dict[str, Any]:
        """Return length, hash, and full text of the last prompt sent via call_llm (thread-local)."""
        return {
            "prompt_len": getattr(self._prompt_local, "last_prompt_len", None),
            "prompt_hash": getattr(self._prompt_local, "last_prompt_hash", None),
            "prompt_text": getattr(self._prompt_local, "last_prompt_text", None),
        }

    @abstractmethod
    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction BEFORE seeing ground truth. Returns (answer, metadata)."""
        pass

    @abstractmethod
    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Learn from a batch of evaluation results.

        Args:
            batch_results: List of dicts, each containing:
                - input: str
                - prediction: str
                - ground_truth: str
                - was_correct: bool
                - metadata: dict (optional)

        This is called AFTER all predictions in the batch are complete.
        The memory system can analyze patterns across the batch.
        """
        pass

    def get_context_length(self) -> int:
        """Return the character length of context actually injected per query.

        Override in subclasses where the injected context differs from stored state
        (e.g., fewshot memories that store all examples but only inject N).
        """
        return len(self.get_state())

    @abstractmethod
    def get_state(self) -> str:
        """Return serializable state for checkpointing."""
        pass

    @abstractmethod
    def set_state(self, state: str) -> None:
        """Restore state from serialized representation."""
        pass

"""Retrieve pairs of similar cases whose verified answers differ."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """The labeled cases are selected because they resemble the current problem. Some similar cases have different verified answers, so compare the facts that distinguish them. The answers below are ground truth; previous model guesses are not included. Follow the current problem's own instructions.

{examples}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]}}"""


def _features(text: str) -> Counter[str]:
    result: Counter[str] = Counter()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result[run] += 1
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 900) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(token, 0.0) for token, value in left.items())


class Candidate(MemorySystem):
    """Build query-relevant, ground-truth-only boundary pairs at prediction time."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 7600
        self.max_pairs = 3
        self._last_context = ""

    def _vectors(self) -> tuple[list[dict[str, float]], dict[str, float]]:
        documents = [_features(example["input"]) for example in self.examples]
        frequency: Counter[str] = Counter()
        for document in documents:
            frequency.update(document.keys())
        count = len(documents)
        inverse = {
            token: math.log(1.0 + (count + 1) / (value + 1))
            for token, value in frequency.items()
        }
        vectors: list[dict[str, float]] = []
        for document in documents:
            total = sum(document.values()) or 1
            raw = {token: value / total * inverse[token] for token, value in document.items()}
            norm = math.sqrt(sum(value * value for value in raw.values())) or 1.0
            vectors.append({token: value / norm for token, value in raw.items()})
        return vectors, inverse

    def _select_pairs(self, query: str) -> list[tuple[int, int]]:
        if len(self.examples) < 2:
            return []
        vectors, inverse = self._vectors()
        query_counts = _features(query)
        query_raw = {token: value * inverse.get(token, 0.0) for token, value in query_counts.items()}
        norm = math.sqrt(sum(value * value for value in query_raw.values())) or 1.0
        query_vector = {token: value / norm for token, value in query_raw.items()}
        query_scores = [_cosine(query_vector, vector) for vector in vectors]
        pairs: list[tuple[float, int, int]] = []
        for left in range(len(self.examples)):
            for right in range(left + 1, len(self.examples)):
                if self.examples[left]["target"] == self.examples[right]["target"]:
                    continue
                both = min(query_scores[left], query_scores[right])
                if both <= 0:
                    continue
                pair_similarity = _cosine(vectors[left], vectors[right])
                score = 0.65 * both + 0.35 * (query_scores[left] + query_scores[right]) / 2
                score += 0.20 * pair_similarity
                pairs.append((score, left, right))
        pairs.sort(reverse=True)
        selected: list[tuple[int, int]] = []
        used: set[int] = set()
        for _, left, right in pairs:
            if left in used or right in used:
                continue
            selected.append((left, right))
            used.update((left, right))
            if len(selected) >= self.max_pairs:
                break
        if not selected:
            nearest = sorted(range(len(self.examples)), key=lambda i: (query_scores[i], i), reverse=True)
            if len(nearest) >= 2:
                selected.append((nearest[0], nearest[1]))
        return selected

    def _format_examples(self, query: str) -> str:
        parts: list[str] = []
        used = 0
        for pair_number, (left, right) in enumerate(self._select_pairs(query), start=1):
            first, second = self.examples[left], self.examples[right]
            part = (
                f"Similar case pair {pair_number}:\n"
                f"Case A: {_clip(first['input'])}\nVerified answer A: {first['target']}\n"
                f"Case B: {_clip(second['input'])}\nVerified answer B: {second['target']}"
            )
            remaining = self.context_budget - used
            if remaining < 150:
                break
            if len(part) > remaining:
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context = "\n\n".join(parts)
        return self._last_context or "No paired examples are available yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "retrieved_pairs": self._last_context.count("Similar case pair"),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(example["input"], example["target"]) for example in self.examples}
        for row in batch_results:
            item = {"input": _source_text(row), "target": str(row["ground_truth"])}
            key = (item["input"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)

    def get_context_length(self) -> int:
        return len(self._last_context)

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
        self._last_context = ""

"""Retrieve complete labeled examples while discounting repeated vocabulary."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Use the relevant labeled examples as demonstrations. Repeated wording may be boilerplate; match the substantive content and follow the current problem's instructions.

{examples}

Current problem:
{input}

Return JSON with a concise final_answer, preserving the answer form requested by the problem.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]}}"""


def _features(text: str) -> list[str]:
    result: list[str] = []
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.extend(run[i : i + 2] for i in range(len(run) - 1))
            result.extend(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result.append(run)
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1350) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Query-conditioned BM25 retrieval with explicit boilerplate discounting."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 12500
        self.max_examples = 14
        self._last_context = ""

    def _rank(self, query: str) -> list[tuple[float, int]]:
        if not self.examples:
            return []
        documents = [_features(example["input"]) for example in self.examples]
        document_frequency: Counter[str] = Counter()
        for document in documents:
            document_frequency.update(set(document))
        count = len(documents)
        average_length = sum(map(len, documents)) / max(1, count)
        query_counts = Counter(_features(query))
        ranked: list[tuple[float, int]] = []
        for index, document in enumerate(documents):
            term_counts = Counter(document)
            score = 0.0
            for token, query_count in query_counts.items():
                frequency = document_frequency.get(token, 0)
                term_count = term_counts.get(token, 0)
                if not frequency or not term_count:
                    continue
                # Near-universal terms contribute little; the hard taper also
                # prevents repeated prompt boilerplate from dominating matches.
                prevalence = frequency / count
                if prevalence >= 0.92:
                    continue
                idf = math.log(1.0 + (count - frequency + 0.5) / (frequency + 0.5))
                idf *= max(0.08, 1.0 - prevalence**2)
                denominator = term_count + 1.2 * (
                    0.25 + 0.75 * len(document) / max(1.0, average_length)
                )
                score += min(query_count, 2) * idf * term_count * 2.2 / denominator
            ranked.append((score, index))
        ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return ranked

    def _format_examples(self, query: str) -> str:
        parts: list[str] = []
        used = 0
        ranked = self._rank(query)
        selected = [index for _, index in ranked[: self.max_examples]]
        for index in selected:
            example = self.examples[index]
            part = f"Q: {_clip(example['input'])}\nA: {example['target']}"
            remaining = self.context_budget - used
            if remaining < 100:
                break
            if len(part) > remaining:
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context = "\n\n".join(parts)
        return self._last_context or "No learned examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "retrieved_examples": len(
                [part for part in self._last_context.split("\n\n") if part]
            ),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(example["input"], example["target"]) for example in self.examples}
        for row in batch_results:
            item = {"input": _source_text(row), "target": str(row["ground_truth"])}
            key = (item["input"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)

    def get_context_length(self) -> int:
        return len(self._last_context)

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
        self._last_context = ""

