            weight = {t: (1 + math.log(c)) * idf.get(t, 0) for t, c in doc.items()}
            norm = math.sqrt(sum(v * v for v in weight.values())) or 1.0
            score = sum(v * weight.get(t, 0) for t, v in qweight.items()) / (qnorm * norm)
            scored.append((score, i))
